<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Lembaga; use Illuminate\Http\Request; use Inertia\Inertia;
class LembagaController extends Controller { public function index(){return Inertia::render('Admin/Lembaga',['lembagas'=>Lembaga::latest()->get()]);} public function store(Request $r){$d=$r->validate(['nama'=>'required|max:255','singkatan'=>'nullable|max:50','ketua'=>'nullable|max:255','kontak'=>'nullable|max:100','deskripsi'=>'nullable','program'=>'nullable','aktif'=>'boolean']);Lembaga::create($d);return back();} public function update(Request $r,Lembaga $lembaga){$lembaga->update($r->validate(['nama'=>'required|max:255','singkatan'=>'nullable|max:50','ketua'=>'nullable|max:255','kontak'=>'nullable|max:100','deskripsi'=>'nullable','program'=>'nullable','aktif'=>'boolean']));return back();} public function destroy(Lembaga $lembaga){$lembaga->delete();return back();} }
